package in.paisa.personal;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;

public class UpgradeTest {
 static int checks=0;static void check(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}
 static JSONObject row(String id,String kind,long amount,String person)throws Exception{return new JSONObject().put("id",id).put("kind",kind).put("amount",amount).put("title",id).put("accountId","bank").put("account","Bank").put("date",System.currentTimeMillis()).put("person",person).put("note","");}
 static JSONObject state(JSONArray rows)throws Exception{return new JSONObject().put("version",3).put("entries",rows).put("accounts",new JSONArray().put(new JSONObject().put("id","bank").put("name","Bank").put("type","bank").put("opening",0))).put("bills",new JSONArray()).put("subscriptions",new JSONArray()).put("settings",new JSONObject().put("cycleStartDay",25).put("monthBudget",100000).put("categoryBudgets",new JSONObject()));}
 public static void main(String[] args)throws Exception{
  long now=LocalDate.of(2026,11,18).atTime(12,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();long[] cycle=Ledger.cycle(now,25);check(Instant.ofEpochMilli(cycle[0]).atZone(ZoneId.systemDefault()).toLocalDate().toString().equals("2026-10-25"),"native salary cycle");check(Ledger.advance("2026-02-28","monthly",31).equals("2026-03-31"),"native anchor day");
  JSONArray rows=new JSONArray().put(row("l1","lend",50000,"Alice")).put(row("l2","lend",70000,"Alice")).put(row("r1","receive",30000,"Alice").put("loanId","l2"));JSONObject data=state(rows);Ledger.validate(data);check(Ledger.loanBalances(rows).get("l2")==40000,"linked partial repayment");
  try{rows.put(row("r2","receive",50000,"Alice").put("loanId","l2"));Ledger.validate(data);throw new AssertionError("oversettlement accepted");}catch(IllegalArgumentException expected){checks++;}rows.remove(rows.length()-1);
  data.getJSONArray("accounts").getJSONObject(0).put("deleted",true);try{Ledger.validate(data);throw new AssertionError("missing account accepted");}catch(IllegalArgumentException expected){checks++;}data.getJSONArray("accounts").getJSONObject(0).remove("deleted");
  SmsParser.Parsed atm=SmsParser.parse("VM-HDFCBK","INR 2000 withdrawn at ATM from A/c XX1234. Avl Bal INR 15000",now);check(atm!=null&&atm.cashWithdrawal&&atm.kind.equals("transfer"),"ATM classified as transfer");check(atm.balance==1500000,"balance extracted separately");check(atm.accountId.contains("1234"),"own account identity");
  JSONObject bill=NoticeParser.bill("HDFC credit card XX4281 total amount due INR 5000. Minimum amount due INR 500. Due on 25-Nov-2026", "HDFC",now);check(bill!=null&&bill.getLong("amount")==500000,"total, not minimum due");check(bill.getString("due").equals("2026-11-25"),"bill due date");check(NoticeParser.bill("Card XX4281 minimum amount due INR 500 due on 25-Nov-2026","HDFC",now)==null,"minimum-only alert ignored");
  String decoded=EmailText.decode("Content-Transfer-Encoding: base64\r\n\r\n"+Base64.getEncoder().encodeToString("<p>INR 500 debited from bank account XX1234 to ALICE</p>".getBytes(StandardCharsets.UTF_8)));check(decoded.contains("500 debited")&&!decoded.contains("<p>"),"email decoded as text");
  byte[] plain=data.toString().getBytes(StandardCharsets.UTF_8);char[] password="A strong backup पासवर्ड".toCharArray();byte[] encoded=BackupCipher.encrypt(plain,password);check(Arrays.equals(plain,BackupCipher.decrypt(encoded,password)),"encrypted snapshot round trip");check(!Arrays.equals(encoded,BackupCipher.encrypt(plain,password)),"fresh salt/nonce");
  try{BackupCipher.decrypt(encoded,"wrong-password".toCharArray());throw new AssertionError("wrong password accepted");}catch(IllegalArgumentException expected){checks++;}
  encoded[encoded.length-1]^=1;try{BackupCipher.decrypt(encoded,password);throw new AssertionError("tampering accepted");}catch(IllegalArgumentException expected){checks++;}
  try{BackupCipher.encrypt(plain,"short".toCharArray());throw new AssertionError("short password accepted");}catch(IllegalArgumentException expected){checks++;}
  String before="{\"id\":\"x\",\"category\":\"Travel\",\"note\":\"Metro pass\",\"sources\":[\"SMS\"]}",after="{\"id\":\"x\",\"category\":\"Food\",\"note\":\"Metro pass\",\"sources\":[\"SMS\"]}";JSONObject current=new JSONObject(after).put("sources",new JSONArray().put("SMS").put("Bank notification"));check(MutationGuard.unchanged(current.toString(),after),"Undo accepts a later source capture");JSONObject reverted=MutationGuard.restore(current,before);check(reverted.getString("category").equals("Travel")&&reverted.getString("note").equals("Metro pass")&&reverted.getJSONArray("sources").length()==2,"Undo preserves notes and later source evidence");check(!MutationGuard.unchanged(new JSONObject(after).put("note","Later user edit").toString(),after),"Undo rejects overwriting later user edit");
  SmsParser.Parsed payment=SmsParser.parse("VM-HDFCBK","Rs 500 debited from A/c XX1234 to CAFE UPI Ref 123456789123",now);JSONObject captured=row("captured","expense",50000,"").put("date",now).put("reference",payment.reference).put("bank",payment.bank).put("accountId",payment.accountId).put("merchantKey",payment.merchantKey).put("title",payment.title).put("source","SMS");check(CaptureMatcher.sameReference(payment,captured),"same reference and account matches");check(!CaptureMatcher.sameReference(payment,new JSONObject(captured.toString()).put("bank","ICICI Bank")),"same reference at different known bank does not merge");check(!CaptureMatcher.sameReference(payment,new JSONObject(captured.toString()).put("accountId","bank:hdfc-bank:5678")),"different own account does not auto merge");check(CaptureMatcher.possible(payment,captured,now+500,"Bank notification"),"SMS/push candidate recognised");check(!CaptureMatcher.possible(payment,captured,now+500,"SMS"),"same-source repeated payment not blindly merged");check(!CaptureMatcher.possible(payment,captured,now+86400000,"Bank notification"),"same merchant tomorrow is a new payment");
  check(!EmailText.hasFinancialContext("I paid Rs 500 for dinner, thanks"),"ordinary personal email not auto processed");check(EmailText.hasFinancialContext("INR 500 debited from HDFC bank account"),"bank email context recognised");
  SmsParser.Parsed receipt=SmsParser.parse("VM-HDFCBK","Payment of INR 500 received towards HDFC credit card XX4281. UPI Ref 456789123456",now),debit=SmsParser.parse("VM-SBIBNK","INR 500 debited from SBI bank account XX1234 towards HDFC credit card bill. UPI Ref 456789123456",now);check(receipt.kind.equals("card_payment")&&receipt.accountId.equals("bank:default")&&!receipt.cardAccountId.isEmpty(),"card receipt never invents a funding bank account");check(debit.kind.equals("card_payment"),"funding debit for card bill is not shopping");JSONObject funding=row("funding","card_payment",50000,"").put("reference",debit.reference).put("bank",debit.bank).put("accountId",debit.accountId);check(CaptureMatcher.sameReference(receipt,funding),"card receipt and funding debit share one payment");check(SmsParser.parse("VM-HDFCBK","Rs 500 paid to SHOP using credit card XX4281",now).kind.equals("expense"),"ordinary card purchase stays an expense");
  check(debit.bank.equals("SBI"),"funding bank wins over destination card bank in the same message");
  check(Ledger.nextDue(new JSONObject().put("nextDue","2026-11-20").put("cycle","monthly").put("anchorDay",20),now).equals("2026-12-20"),"early subscription payment advances renewal");
  System.out.println(checks+" native ledger / parser / encrypted-backup checks passed");
 }
}
